public class PriceCache(ShopDbContext db)
{
    private readonly Dictionary<int, decimal> _prices = new();

    public async Task<decimal> GetPriceAsync(int productId)
    {
        if (_prices.TryGetValue(productId, out var price))
            return price;

        var product = await db.Products.FindAsync(productId);
        _prices[productId] = product!.Price;
        return product.Price;
    }
}

public class DashboardService(AppDbContext db)
{
    public async Task<DashboardDto> GetAsync(int userId, CancellationToken ct)
    {
        var ordersTask = db.Orders.CountAsync(o => o.UserId == userId, ct);
        var ticketsTask = db.Tickets.CountAsync(t => t.UserId == userId, ct);
        var lastLoginTask = db.Logins
            .Where(l => l.UserId == userId)
            .MaxAsync(l => (DateTime?)l.At, ct);

        await Task.WhenAll(ordersTask, ticketsTask, lastLoginTask);

        return new DashboardDto(ordersTask.Result, ticketsTask.Result,
            lastLoginTask.Result);
    }
}

[HttpGet("orders")]
public async Task<List<OrderListItem>> GetOrders(CancellationToken ct)
{
    var orders = await _db.Orders
        .Where(o => o.Status == OrderStatus.Open)
        .ToListAsync(ct);

    var result = new List<OrderListItem>();
    foreach (var order in orders)
    {
        var customer = await _db.Customers
            .FirstAsync(c => c.Id == order.CustomerId, ct);
        var total = await _db.OrderLines
            .Where(l => l.OrderId == order.Id).SumAsync(l => l.Price * l.Qty, ct);
        result.Add(new OrderListItem(order.Id, customer.Name, total));
    }
    return result;
}

