public class InvoiceNumberGenerator
{
    private static int _lastNumber;
    private static string _lastMonth = "";

    public async Task<string> NextAsync(CancellationToken ct)
    {
        lock ("invoice-lock")
        {
            var month = DateTime.Now.ToString("yyyyMM");
            if (month != _lastMonth) { _lastMonth = month; _lastNumber = 0; }
            _lastNumber++;
        }
        await _db.SaveCounterAsync(_lastNumber, ct);
        return $"FV/{_lastMonth}/{_lastNumber:D5}";
    }
}

public async Task<byte[]> ExportAsync(int reportId)
{
    var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
    var conn = new SqlConnection(_cs);
    await conn.OpenAsync(cts.Token);

    var cmd = new SqlCommand("SELECT Name, Amount FROM Lines WHERE ReportId = @id", conn);
    cmd.Parameters.AddWithValue("@id", reportId);
    var reader = await cmd.ExecuteReaderAsync(cts.Token);

    var ms = new MemoryStream();
    var writer = new StreamWriter(ms);
    while (await reader.ReadAsync(cts.Token))
        await writer.WriteLineAsync($"{reader.GetString(0)};{reader.GetDecimal(1)}");
    await writer.FlushAsync();
    return ms.ToArray();
}

