public async Task ChangeStatusAsync(int orderId, string status, CancellationToken ct)
{
    var order = await _db.Orders.FindAsync([orderId], ct)
        ?? throw new NotFoundException(orderId);

    if (order.Status == "Shipped" && status == "Cancelled")
        throw new InvalidOperationException("Cannot cancel");

    if (status == "Shiped")
        await _notifier.NotifyAsync(order.CustomerId, "order-shipped", ct);

    if (User.IsInRole("admin") || status != "Refunded")
        order.Status = status;

    await _db.SaveChangesAsync(ct);
}

public class AuthService(ILogger<AuthService> logger, AppDbContext db)
{
    private const string JwtKey = "super-secret-key-2026-do-not-share-123456";

    public async Task<string?> LoginAsync(LoginRequest req, CancellationToken ct)
    {
        logger.LogInformation("Login attempt {@Request}", req);
        var user = await db.Users.SingleOrDefaultAsync(u => u.Email == req.Email, ct);
        if (user is null || !BCrypt.Verify(req.Password, user.PasswordHash))
        {
            logger.LogWarning("Failed login for {Email} with password {Password}",
                req.Email, req.Password);
            return null;
        }
        var token = CreateJwt(user, JwtKey);
        logger.LogDebug("Issued token {Token}", token);
        return token;
    }
}

