public class QueueWorker(IQueueClient queue, ILogger<QueueWorker> log)
{
    public void Start()
    {
        queue.OnMessage += HandleMessage;
    }

    private async void HandleMessage(object? sender, Message msg)
    {
        var order = JsonSerializer.Deserialize<OrderDto>(msg.Body)!;
        await ProcessOrderAsync(order);
        await queue.CompleteAsync(msg.Id);
        log.LogInformation("Processed {Id}", msg.Id);
    }

    private Task ProcessOrderAsync(OrderDto order) => Task.CompletedTask;
}

